/* ==== INTERFACE ====
方向：拟物主义（Skeuomorphism）结合黑胶唱片与精密声学硬件的物理感知。以暖调唱机实木基座、黑色胶木同心纹、拉丝金属面板与压铸阴影为视觉线索，为博物馆观众提供具备真实操作触感与物理厚度的界面层级。
reference style:07-skeuomorphism
token --bg：页面默认基底色（温暖复古纸帛暖白 #f6f3ee）。
token --text：正文主要深色文字（黑胶碳墨色 #1c1917）。
token --font-sans：清晰开阔的西文与中文正文无衬线字体栈。
token --font-serif：温暖且具物理雕刻质感的标题衬线字体栈。
class .nt-title：普通页主标题（Noto Serif SC 600 + Fraunces 600，--fs-h1: 38px / 1.25）；封面主标题可加大至 56px（--fs-hero）。
class .nt-subtitle：区块副题与章节引导（--fs-h2: 24px / 1.35）。
class .nt-lead：导读与核心设问文字（--fs-lead: 20px / 1.5）。
class .nt-body：正文与原理解释（--fs-body: 16px / 1.6）。
class .nt-label：操作旋钮、唱针指示、声波图例小标（--fs-label: 14px / 1.4）。
class .nt-plate：物理拟物底盘/唱机金属面板（带有金属微边框、下沉式内阴影与柔和投射）。
class .nt-vinyl-disc：黑胶同心刻纹圆形装饰或转盘容器，呈现同心微光与中心标签槽。
class .nt-button：具有实体按压深度、边缘高光与厚度阴影的交互按钮。
class .nt-badge：金属铭牌或状态指示标签（机械振动 vs 电信号）。
class .nt-signal-trace：波形与信号传输连接线，承载机械物理振动与电信号的对比演示。
variant opening：开篇引入页，暖木与黑胶质感交织，强化实体展品直观意象。
默认：未设 data-variant 时为清晰明晰的展品说明台模式。
品牌：无全局品牌 logo，保持纯粹的博物馆科普展签视野。
==== /INTERFACE ==== */

/* 字体声明：Fraunces (EN Serif), Noto Serif SC (ZH Serif), Inter (EN Sans), Noto Sans SC (ZH Sans) */
@font-face {
  font-family: "NTF-noto-serif-sc";
  src: url("fonts/library/noto-serif-sc/face-0.ttf");
  font-weight: 200 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-fraunces";
  src: url("fonts/library/fraunces/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-1.ttf");
  font-weight: 100 900;
  font-style: italic;
  font-display: swap;
}

@font-face {
  font-family: "NTF-noto-sans-sc";
  src: url("fonts/library/noto-sans-sc/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

:root {
  /* 颜色层级：唱机柚木/胡桃木、精细黄铜、黑胶唱片与暖纸 */
  --bg: #f5f2eb;
  --bg-subtle: #eae5da;
  --text: #1f1d1a;
  --text-muted: #6e675f;
  --text-light: #f5f2eb;

  /* 材质与质感点缀色 */
  --brass: #c8963e;
  --brass-dark: #916823;
  --brass-light: #fae0a2;
  --vinyl-black: #141312;
  --vinyl-groove: #282624;
  --wood-rim: #443224;
  --signal-mech: #d9633b;  /* 机械振动：触觉暖红橙 */
  --signal-elec: #2b7a78;  /* 电信号与扬声器：电磁清蓝绿 */

  --focus: #c8963e;

  /* 拟物物理光影系统 (上光下暗、压铸深槽、浮雕凸起) */
  --shadow-plate: 0 1px 1px rgba(255, 255, 255, 0.8) inset, 0 10px 24px -6px rgba(44, 34, 24, 0.12), 0 2px 6px rgba(44, 34, 24, 0.08);
  --shadow-recessed: inset 0 2px 5px rgba(20, 18, 16, 0.28), inset 0 1px 2px rgba(20, 18, 16, 0.2), 0 1px 0 rgba(255, 255, 255, 0.7);
  --shadow-knob: 0 4px 8px rgba(20, 18, 16, 0.25), 0 1px 2px rgba(20, 18, 16, 0.15), inset 0 1px 1px rgba(255, 255, 255, 0.6);
  --shadow-pressed: inset 0 3px 6px rgba(0, 0, 0, 0.35), 0 1px 0 rgba(255, 255, 255, 0.5);

  /* 字体栈 */
  --font-serif: "NTF-fraunces", "NTF-noto-serif-sc", "Songti SC", serif;
  --font-sans: "NTF-inter", "NTF-noto-sans-sc", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-mono: "NTF-inter", monospace;

  /* 字阶 (1600x900 逻辑画布基准) */
  --fs-hero: 52px;
  --fs-h1: 36px;
  --fs-h2: 24px;
  --fs-lead: 18px;
  --fs-body: 16px;
  --fs-label: 14px;
  --fs-tick: 12px;

  /* 间距与倒角 */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 16px;
  --radius-round: 9999px;
}

/* 舞台容器设定 */
#stage {
  background-color: var(--bg);
  background-image: 
    radial-gradient(ellipse at 80% 10%, rgba(200, 150, 62, 0.08) 0%, transparent 60%),
    linear-gradient(180deg, #f8f6f0 0%, #eee8dd 100%);
  color: var(--text);
  font-family: var(--font-sans);
  overflow: hidden;
  box-sizing: border-box;
}

/* 开篇引入变体 (微暗温暖木台氛围，强化实体展品聚集焦点) */
html[data-variant="opening"] #stage {
  background-color: #211c17;
  background-image: 
    radial-gradient(circle at 65% 45%, rgba(68, 50, 36, 0.6) 0%, transparent 70%),
    linear-gradient(135deg, #181512 0%, #28211b 100%);
  color: var(--text-light);
}

html[data-variant="opening"] .nt-title,
html[data-variant="opening"] .nt-subtitle {
  color: #fff9f0;
}

html[data-variant="opening"] .nt-lead,
html[data-variant="opening"] .nt-text-muted {
  color: #c4b8aa;
}

/* 标题类目规范 */
.nt-title {
  font-family: var(--font-serif);
  font-size: var(--fs-h1);
  font-weight: 600;
  line-height: 1.25;
  letter-spacing: -0.01em;
  color: var(--text);
  margin: 0;
}

.nt-title--hero {
  font-size: var(--fs-hero);
  line-height: 1.15;
}

.nt-subtitle {
  font-family: var(--font-serif);
  font-size: var(--fs-h2);
  font-weight: 600;
  line-height: 1.35;
  color: var(--text);
  margin: 0;
}

.nt-lead {
  font-size: var(--fs-lead);
  line-height: 1.55;
  color: var(--text-muted);
}

.nt-body {
  font-size: var(--fs-body);
  line-height: 1.6;
  color: var(--text);
}

.nt-label {
  font-size: var(--fs-label);
  font-weight: 500;
  line-height: 1.4;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.nt-tick {
  font-size: var(--fs-tick);
  font-family: var(--font-mono);
  color: var(--text-muted);
}

/* 拟物物理底板 / 仪器金属托盘 */
.nt-plate {
  background: linear-gradient(175deg, #ffffff 0%, #f7f4ed 60%, #ece6d8 100%);
  border: 1px solid rgba(255, 255, 255, 0.8);
  border-bottom-color: rgba(160, 145, 130, 0.4);
  border-right-color: rgba(160, 145, 130, 0.3);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-plate);
  position: relative;
}

/* 嵌入式凹槽面板（放置唱片、放大器读数区） */
.nt-well {
  background: #231f1c;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-recessed);
  border: 1px solid #3c342e;
  border-top-color: #12100e;
  color: #e8e2d8;
  position: relative;
}

/* 黑胶同心纹盘片形态 */
.nt-vinyl-disc {
  width: 320px;
  height: 320px;
  border-radius: 50%;
  background: 
    radial-gradient(circle, #7e1717 0%, #4a0d0d 30%, transparent 31%),
    repeating-radial-gradient(
      circle at center,
      #131211 0px,
      #1b1918 1px,
      #131211 2px,
      #22201e 3px
    );
  box-shadow: 
    0 12px 32px rgba(0, 0, 0, 0.45),
    0 2px 6px rgba(0, 0, 0, 0.3),
    inset 0 0 0 2px rgba(255, 255, 255, 0.08);
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.nt-vinyl-disc::after {
  content: "";
  position: absolute;
  width: 14px;
  height: 14px;
  background: #e6dfd3;
  border-radius: 50%;
  box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.8), 0 0 0 2px #5c1111;
}

/* 实物感按钮组件（具备物理厚度与按压反馈） */
.nt-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  font-weight: 600;
  padding: 10px 22px;
  border-radius: var(--radius-md);
  border: 1px solid rgba(255, 255, 255, 0.6);
  border-top-color: rgba(255, 255, 255, 0.9);
  border-bottom-color: rgba(0, 0, 0, 0.25);
  background: linear-gradient(180deg, #faf7f0 0%, #e2dacf 100%);
  color: var(--text);
  box-shadow: var(--shadow-knob);
  cursor: pointer;
  user-select: none;
  transition: transform 0.1s ease, box-shadow 0.1s ease;
}

.nt-button:hover {
  background: linear-gradient(180deg, #ffffff 0%, #e9e2d7 100%);
}

.nt-button:active,
.nt-button[aria-pressed="true"],
.nt-button.is-active {
  background: linear-gradient(180deg, #d3cbbe 0%, #dfd8cb 100%);
  box-shadow: var(--shadow-pressed);
  transform: translateY(1px);
}

.nt-button--brass {
  background: linear-gradient(180deg, #e4af51 0%, #b8832a 100%);
  color: #2b1c03;
  border-color: #f7d287;
  border-bottom-color: #724c08;
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.3);
}

.nt-button--brass:hover {
  background: linear-gradient(180deg, #ecc16b 0%, #c48f32 100%);
}

.nt-button--brass:active,
.nt-button--brass[aria-pressed="true"] {
  background: linear-gradient(180deg, #a67520 0%, #be8b2f 100%);
  box-shadow: inset 0 3px 6px rgba(60, 40, 5, 0.5), 0 1px 0 rgba(255, 255, 255, 0.3);
}

/* 标牌徽章（铜制铭牌感与清晰分类） */
.nt-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  font-size: var(--fs-tick);
  font-weight: 600;
  letter-spacing: 0.05em;
  background: #e2ddd3;
  color: #433d36;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.8), 0 1px 2px rgba(0, 0, 0, 0.1);
  border: 1px solid #c9c1b3;
}

.nt-badge--mech {
  background: #fbeee8;
  color: var(--signal-mech);
  border-color: #f2cfc2;
}

.nt-badge--elec {
  background: #e6f3f2;
  color: var(--signal-elec);
  border-color: #bce0de;
}

/* 刻度线与引导指示 */
.nt-scale-track {
  height: 6px;
  background: #181614;
  border-radius: 3px;
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.7), 0 1px 0 rgba(255, 255, 255, 0.15);
  position: relative;
}

.nt-scale-thumb {
  width: 20px;
  height: 28px;
  background: linear-gradient(180deg, #f0ede6 0%, #b8b1a4 100%);
  border-radius: 2px;
  box-shadow: 0 3px 6px rgba(0,0,0,0.35), inset 0 1px 0 #ffffff;
  border: 1px solid #7c7467;
  cursor: grab;
}

/* 信号流转路径与动态可视化微线 */
.nt-signal-path {
  fill: none;
  stroke: var(--text-muted);
  stroke-width: 2px;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.nt-signal-path--mech {
  stroke: var(--signal-mech);
  stroke-dasharray: 4 2;
}

.nt-signal-path--elec {
  stroke: var(--signal-elec);
}

/* 交互卡片悬停与聚焦 */
.nt-interactive-card {
  transition: transform 0.2s cubic-bezier(0.2, 0.8, 0.2, 1), box-shadow 0.2s ease;
  cursor: pointer;
}

.nt-interactive-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 1px 1px rgba(255, 255, 255, 0.9) inset, 0 16px 32px -8px rgba(44, 34, 24, 0.16), 0 4px 10px rgba(44, 34, 24, 0.08);
}
